<?php
declare(strict_types=1);
final class SystemSettingModel
{
 public function defaults():array{return ['institution_name'=>'Instituto Superior Tecnológico El Libertador','file_max_mb'=>20,'file_total_max_mb'=>50,'file_extensions'=>['pdf','docx','zip']];}
 public function all():array{$values=$this->defaults();foreach(Database::connection()->query('SELECT setting_key,setting_value FROM system_settings')->fetchAll() as $row){if(!array_key_exists($row['setting_key'],$values))continue;$values[$row['setting_key']]=$row['setting_key']==='file_extensions'?(json_decode($row['setting_value'],true)?:[]):($row['setting_key']==='institution_name'?$row['setting_value']:(int)$row['setting_value']);}return $values;}
 public function save(array $input,int $actor):void{$name=trim((string)($input['institution_name']??''));$max=(int)($input['file_max_mb']??0);$total=(int)($input['file_total_max_mb']??0);$extensions=array_values(array_intersect(['pdf','docx','zip'],array_map('strval',(array)($input['file_extensions']??[]))));if(mb_strlen($name)<5||mb_strlen($name)>180)throw new InvalidArgumentException('Ingresa un nombre institucional válido.');if($max<1||$max>100||$total<$max||$total>500)throw new InvalidArgumentException('El límite individual debe estar entre 1 y 100 MB y el total entre ese valor y 500 MB.');if(!$extensions)throw new InvalidArgumentException('Mantén al menos un formato de archivo habilitado.');Database::transaction(function(PDO $d)use($name,$max,$total,$extensions,$actor):void{$q=$d->prepare('INSERT INTO system_settings(setting_key,setting_value,updated_by) VALUES(:key,:value,:actor) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)');foreach(['institution_name'=>$name,'file_max_mb'=>(string)$max,'file_total_max_mb'=>(string)$total,'file_extensions'=>json_encode($extensions)] as $key=>$value)$q->execute(['key'=>$key,'value'=>$value,'actor'=>$actor]);$a=$d->prepare("INSERT INTO admin_audit_log(actor_user_id,action,entity_type,details) VALUES(:actor,'settings_updated','settings',:details)");$a->execute(['actor'=>$actor,'details'=>json_encode(['file_max_mb'=>$max,'file_total_max_mb'=>$total,'file_extensions'=>$extensions])]);});}
}
